SELECT COUNT(*) FROM software
WHERE slug = #{slug}

    AND id <> #{excludeId}

SELECT id, software_id, version, channel, notes_zh, notes_en, published_at, status, created_at
FROM software_release
WHERE id = #{id}

SELECT COUNT(*) FROM software_release
WHERE software_id = #{softwareId} AND version = #{version} AND channel = #{channel}

    AND id <> #{excludeId}

SELECT COUNT(*) FROM release_asset
WHERE release_id = #{releaseId}
  AND platform = #{platform}
  AND arch = #{arch}
  AND package_type = #{packageType}
